            #region Combine
            public ErrorMask Combine(ErrorMask? rhs)
            {
                if (rhs == null) return this;
                var ret = new ErrorMask();
                ret.EDID = this.EDID.Combine(rhs.EDID);
                ret.ObjectBounds = this.ObjectBounds.Combine(rhs.ObjectBounds, (l, r) => l.Combine(r));
                ret.PHST = this.PHST.Combine(rhs.PHST);
                ret.PreviewTransform = this.PreviewTransform.Combine(rhs.PreviewTransform);
                ret.DefaultLayer = this.DefaultLayer.Combine(rhs.DefaultLayer);
                ret.SnapTemplate = this.SnapTemplate.Combine(rhs.SnapTemplate);
                ret.XALG = this.XALG.Combine(rhs.XALG);
                ret.FormTags = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.FormTags?.Overall, rhs.FormTags?.Overall), Noggog.ExceptionExt.Combine(this.FormTags?.Specific, rhs.FormTags?.Specific));
                ret.ObjectPlacementDefaults = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, ObjectPlacementDefault.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.ObjectPlacementDefaults?.Overall, rhs.ObjectPlacementDefaults?.Overall), Noggog.ExceptionExt.Combine(this.ObjectPlacementDefaults?.Specific, rhs.ObjectPlacementDefaults?.Specific));
                ret.ForcedLocRefType = this.ForcedLocRefType.Combine(rhs.ForcedLocRefType);
                ret.Model = this.Model.Combine(rhs.Model, (l, r) => l.Combine(r));
                ret.ENLM = this.ENLM.Combine(rhs.ENLM);
                ret.ENLT = this.ENLT.Combine(rhs.ENLT);
                ret.ENLS = this.ENLS.Combine(rhs.ENLS);
                ret.AUUV = this.AUUV.Combine(rhs.AUUV);
                ret.XFLG = this.XFLG.Combine(rhs.XFLG);
                ret.Properties = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, ObjectProperty.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.Properties?.Overall, rhs.Properties?.Overall), Noggog.ExceptionExt.Combine(this.Properties?.Specific, rhs.Properties?.Specific));
                ret.FULL = this.FULL.Combine(rhs.FULL);
                ret.Destructible = this.Destructible.Combine(rhs.Destructible, (l, r) => l.Combine(r));
                ret.NAM1 = this.NAM1.Combine(rhs.NAM1);
                ret.LODP = this.LODP.Combine(rhs.LODP);
                ret.STXF = this.STXF.Combine(rhs.STXF);
                ret.NVNM = this.NVNM.Combine(rhs.NVNM);
                ret.MaxAngle = this.MaxAngle.Combine(rhs.MaxAngle);
                ret.Material = this.Material.Combine(rhs.Material);
                ret.LeafAmplitude = this.LeafAmplitude.Combine(rhs.LeafAmplitude);
                ret.LeafFrequency = this.LeafFrequency.Combine(rhs.LeafFrequency);
                ret.DestructibleObjectFactions = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, DestructibleObjectFaction.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.DestructibleObjectFactions?.Overall, rhs.DestructibleObjectFactions?.Overall), Noggog.ExceptionExt.Combine(this.DestructibleObjectFactions?.Specific, rhs.DestructibleObjectFactions?.Specific));
                ret.MNAM = this.MNAM.Combine(rhs.MNAM);
                ret.VMAD = this.VMAD.Combine(rhs.VMAD);
                ret.Conditions = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, Condition.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.Conditions?.Overall, rhs.Conditions?.Overall), Noggog.ExceptionExt.Combine(this.Conditions?.Specific, rhs.Conditions?.Specific));
                ret.DSCF = this.DSCF.Combine(rhs.DSCF);
                ret.HGLB = this.HGLB.Combine(rhs.HGLB);
                ret.DOFA = this.DOFA.Combine(rhs.DOFA);
                ret.OPDS = this.OPDS.Combine(rhs.OPDS);
                return ret;
            }
            public static ErrorMask? Combine(ErrorMask? lhs, ErrorMask? rhs)
            {
                if (lhs != null && rhs != null) return lhs.Combine(rhs);
                return lhs ?? rhs;
            }
